import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`facebook-ads`,heroTitle:`Create your Meta Ads in minutes`,heroSubtitle:`Perplexity Computer designs ad images, writes copy for every variation, and delivers publish-ready creatives — automatically.`,inputUrlCta:`Create my ads`,inputUrlPlaceholder:`www.yourcompany.com`,inputUrlPrefill:`Go to {url} and create a complete Meta Ads creative package. Analyze the brand, product, value proposition, and visual style. Then: (1) Design 20 static feed ad images in 1080x1080 format — vary the layouts across product shots, lifestyle scenes, testimonial cards, comparison graphics, and benefit callouts, (2) Write matching primary text (125 chars), headline (40 chars), and description (30 chars) for each image, (3) Create 5 audience targeting suggestions with interest and behavior combinations, (4) Group the 20 ads into 4 themed ad sets for structured A/B testing, (5) Recommend daily budget allocation across ad sets based on funnel stage. Deliver everything as a creative brief with image mockups, ad copy spreadsheet, targeting specs, and a testing roadmap.`,heroOverlaySteps:[`Analyzing your brand, products, and visual style`,`Designing 20 static ad images across multiple layouts and angles`,`Writing primary text, headlines, and descriptions for each creative`,`Creative brief with ad images, copy, targeting, and testing plan — ready to publish`],generatingSteps:[`Visiting {url} to extract your brand, products, and visual identity`,`Designing an agent to create ad images and write copy variations`,`Configuring audience targeting, ad set structure, and A/B testing plan`,`Setting up creative brief with images, copy, and budget recommendations`],featureSectionTitle:`From URL to ad creatives`,featureCardTitles:[`Connects to your ad tools`,`Ads ready to publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Canva, Google Sheets, Notion, Airtable — Computer delivers ad creatives and copy in the formats your design and media teams already use.`,`Static images. Primary text. Headlines. Targeting specs. Computer delivers a complete creative package your team can upload to Ads Manager immediately.`],capabilitySectionTitle:`Your creative team, on demand`,capabilitySectionSubtitle:`Paste your URL, get back 20 publish-ready ad creatives.`,capabilityCards:[{title:`Ad Image Design`,description:`Computer designs static feed ads across product shots, lifestyle scenes, testimonial cards, and benefit callouts — all matched to your brand.`},{title:`Ad Copy Writing`,description:`Computer writes primary text, headlines, and descriptions for every creative — optimized for Meta's character limits and best practices.`},{title:`Audience Targeting`,description:`Computer builds audience segments with interest and behavior targeting — so your ads reach the people most likely to convert.`},{title:`A/B Test Structure`,description:`Computer groups creatives into themed ad sets with a structured testing plan — so you learn what works fast and scale the winners.`},{title:`Learns Your Brand`,description:`Computer remembers your brand colors, imagery style, and past ad performance across sessions — so every batch of creatives gets sharper.`},{title:`Creative Refresh Alerts`,description:`Computer monitors ad fatigue and performance trends — and alerts you when creatives need a refresh or new variations.`}]});export{t as default};
